const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const NL = String.fromCharCode(10);
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const r = items[i].json;
  if (!r || !r.id) continue;
  const unsubscribeUrl = r.unsubscribe_token ? `${r.site_url}/unsubscribe?token=${r.unsubscribe_token}` : '';
  const vars = { ...(r.variables || {}), site_url: r.site_url, postal_address: r.postal_address, unsubscribe_url: unsubscribeUrl };

  // The assessment report is built here from the saved matches the database
  // attached to the row. Every value is escaped; nothing comes from the browser.
  const raw = {};
  if (Array.isArray(vars.matches)) {
    const ms = vars.matches.filter((m) => m && typeof m.title === 'string' && m.title);
    const line = (label, v) => (typeof v === 'string' && v ? `<p style="margin:4px 0"><strong>${label}:</strong> ${esc(v)}</p>` : '');
    raw.matches_html = ms.map((m, n) => {
      const steps = Array.isArray(m.firstSteps) ? m.firstSteps.filter((x) => typeof x === 'string' && x) : [];
      return `<div style="margin:0 0 20px;padding:0 0 12px;border-bottom:1px solid #ddd"><h3 style="margin:0 0 6px">${n + 1}. ${esc(m.title)}</h3>`
        + (typeof m.description === 'string' && m.description ? `<p style="margin:4px 0">${esc(m.description)}</p>` : '')
        + line('Why you', m.whyYou) + line('Income range', m.incomeRange) + line('Your unique angle', m.uniqueAngle)
        + (steps.length ? `<p style="margin:4px 0"><strong>First steps:</strong></p><ol style="margin:4px 0">${steps.map((x) => `<li>${esc(x)}</li>`).join('')}</ol>` : '')
        + '</div>';
    }).join('');
    vars.matches_text = ms.map((m, n) => {
      const steps = Array.isArray(m.firstSteps) ? m.firstSteps.filter((x) => typeof x === 'string' && x) : [];
      const parts = [`${n + 1}. ${m.title}`, m.description, m.whyYou && `Why you: ${m.whyYou}`, m.incomeRange && `Income range: ${m.incomeRange}`,
        m.uniqueAngle && `Your unique angle: ${m.uniqueAngle}`, steps.length && `First steps:${NL}${steps.map((x, j) => `  ${j + 1}. ${x}`).join(NL)}`];
      return parts.filter((x) => typeof x === 'string' && x).join(NL);
    }).join(NL + NL);
    if (!ms.length) { delete vars.matches_text; }
    delete vars.matches;
  }

  // An empty string is a legitimate value. Only a missing variable is left in
  // place, which the check below then refuses to send.
  const fill = (tpl, html) => String(tpl || '').replace(/\{\{\s*([a-z_]+)\s*\}\}/g, (m, k) => {
    if (html && typeof raw[k] === 'string' && raw[k]) return raw[k];
    const v = vars[k];
    if (v === undefined || v === null || typeof v === 'object') return m;
    return html ? esc(v) : String(v);
  });
  const subject = fill(r.subject, false);
  const html = fill(r.html, true);
  const text = fill(r.body_text, false);

  let problem = '';
  if (!r.subject || !r.html) problem = `template ${r.template_key} not found`;
  else if ([subject, html, text, r.from_address, r.reply_to].some((s) => String(s).includes('REPLACE_BEFORE_LAUNCH'))) problem = 'a launch placeholder is still unset';
  else if ([subject, html, text].some((s) => /\{\{\s*[a-z_]+\s*\}\}/.test(s))) problem = 'template has an unresolved variable';

  const payload = { from: r.from_address, to: [r.to_email], reply_to: r.reply_to, subject, html, text };
  if (r.kind === 'owner_notice' && vars.lead_email) payload.reply_to = vars.lead_email;
  if (r.unsubscribe_token) {
    payload.headers = {
      'List-Unsubscribe': `<${r.site_url}/api/unsubscribe?token=${r.unsubscribe_token}>`,
      'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click',
    };
  }
  out.push({
    json: { id: r.id, to_email: r.to_email, kind: r.kind, template_key: r.template_key,
            outcome: problem ? 'failed' : '', provider_message_id: '', error: problem,
            payload: problem ? null : payload },
    pairedItem: { item: i },
  });
}
return out;

// Decides what is known about the send. Only a 2xx with a message id is
// 'sent'. A response that proves Resend refused the message is 'failed'.
// Anything else (timeout, network error, 5xx, 409) is 'uncertain': the email
// may have gone out, so it is reported and never retried automatically.
const src = $('Ready to send?').item.json;
const res = $json || {};
const code = Number(res.statusCode);
const body = (res.body && typeof res.body === 'object') ? res.body : {};
let outcome = 'uncertain';
let providerId = '';
let error = '';
if (code >= 200 && code < 300 && body.id) {
  outcome = 'sent';
  providerId = body.id;
} else if ([400, 401, 403, 404, 405, 413, 422, 429].includes(code)) {
  outcome = 'failed';
  error = `Resend ${code}: ${body.message || body.name || 'rejected'}`;
} else {
  error = code ? `Resend ${code}: ${body.message || 'no confirmation'}` : `No response: ${(res.error && (res.error.message || res.error)) || 'unknown'}`;
}
return { json: { id: src.id, to_email: src.to_email, kind: src.kind, template_key: src.template_key,
                 outcome, provider_message_id: providerId, error: String(error).slice(0, 500) } };

